<?php
require_once 'config.php';login_required();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['buat_tugas'])){role_required(['admin','dosen']);try{$lamp=upload_file('lampiran','tugas',['pdf','doc','docx','ppt','pptx','zip'],20);$pdo->prepare("INSERT INTO tugas(mata_kuliah_id,dosen_id,judul,deskripsi,deadline,lampiran) VALUES(?,?,?,?,?,?)")->execute([$_POST['mk'],user()['id'],trim($_POST['judul']),trim($_POST['deskripsi']),$_POST['deadline'],$lamp]);flash('Tugas berhasil dibuat.');redirect('tugas.php');}catch(Throwable $e){$error=$e->getMessage();}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['kumpulkan'])){role_required(['mahasiswa']);try{$file=upload_file('file','pengumpulan',['pdf','doc','docx','ppt','pptx','zip','py','java','php','txt','xlsx'],20);if(!$file)throw new Exception('Pilih file tugas terlebih dahulu.');$tid=(int)$_POST['tugas_id'];$deadline=$pdo->prepare("SELECT deadline FROM tugas WHERE id=?");$deadline->execute([$tid]);$d=$deadline->fetchColumn();$status=(strtotime('now')>strtotime($d))?'terlambat':'terkirim';$sql="INSERT INTO pengumpulan(tugas_id,mahasiswa_id,file,catatan,status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE file=VALUES(file),catatan=VALUES(catatan),status=VALUES(status),submitted_at=CURRENT_TIMESTAMP";$pdo->prepare($sql)->execute([$tid,user()['id'],$file,trim($_POST['catatan']),$status]);flash('Tugas berhasil dikumpulkan.');redirect('tugas.php');}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$pdo->query("SELECT t.*,m.nama AS matkul,u.nama AS dosen FROM tugas t JOIN mata_kuliah m ON m.id=t.mata_kuliah_id JOIN users u ON u.id=t.dosen_id ORDER BY t.deadline ASC")->fetchAll();
$my=[];if(user()['role']==='mahasiswa'){$q=$pdo->prepare("SELECT * FROM pengumpulan WHERE mahasiswa_id=?");$q->execute([user()['id']]);foreach($q as $p)$my[$p['tugas_id']]=$p;}
$mks=$pdo->query("SELECT id,nama FROM mata_kuliah")->fetchAll();$page_title='Tugas';require 'includes/header.php'; ?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h3>Tugas & pengumpulan</h3><p class="muted mb-0">Periksa instruksi, deadline, lalu kirim hasil pekerjaanmu.</p></div></div>
<?php if(!empty($error)): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<?php if(in_array(user()['role'],['admin','dosen'])): ?><div class="form-card mb-4"><h4>Buat tugas baru</h4><form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="buat_tugas" value="1"><div class="col-md-4"><select name="mk" class="form-select" required><option value="">Mata kuliah</option><?php foreach($mks as $m): ?><option value="<?= $m['id'] ?>"><?= e($m['nama']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><input name="judul" class="form-control" placeholder="Judul tugas" required></div><div class="col-md-4"><input type="datetime-local" name="deadline" class="form-control" required></div><div class="col-md-8"><textarea name="deskripsi" class="form-control" placeholder="Deskripsi / instruksi tugas"></textarea></div><div class="col-md-4"><input type="file" name="lampiran" class="form-control"></div><div class="col-12"><button class="btn btn-primary">Publikasikan tugas</button></div></form></div><?php endif; ?>
<div class="row g-3"><?php foreach($rows as $r): ?><div class="col-xl-6"><div class="card-item"><div class="d-flex justify-content-between"><span class="badge badge-soft"><?= e($r['matkul']) ?></span><span class="small deadline">Deadline: <?= date('d M Y H:i',strtotime($r['deadline'])) ?></span></div><h5 class="mt-3"><?= e($r['judul']) ?></h5><p class="muted"><?= nl2br(e($r['deskripsi'])) ?></p><div class="muted small mb-3">Dosen: <?= e($r['dosen']) ?></div><?php if($r['lampiran']): ?><a href="uploads/<?= e($r['lampiran']) ?>" download class="btn btn-sm btn-outline-light mb-3">Unduh lampiran</a><?php endif; ?>
<?php if(user()['role']==='mahasiswa'): $p=$my[$r['id']]??null; ?><div class="border-top pt-3" style="border-color:var(--line)!important"><?php if($p): ?><p class="small mb-2">Status: <span class="badge badge-soft"><?= e($p['status']) ?></span> · Nilai: <b><?= $p['nilai']===null?'Belum dinilai':e($p['nilai']) ?></b></p><?php if($p['feedback']): ?><p class="muted small">Feedback: <?= e($p['feedback']) ?></p><?php endif; ?><?php else: ?><p class="small muted">Belum dikumpulkan</p><?php endif; ?>
<form method="post" enctype="multipart/form-data" class="d-grid gap-2"><input type="hidden" name="kumpulkan" value="1"><input type="hidden" name="tugas_id" value="<?= $r['id'] ?>"><input type="file" name="file" class="form-control form-control-sm" required><input name="catatan" class="form-control form-control-sm" placeholder="Catatan (opsional)"><button class="btn btn-sm btn-primary"><?= $p?'Kirim ulang tugas':'Kumpulkan tugas' ?></button></form></div><?php endif; ?></div></div><?php endforeach; ?><?php if(!$rows): ?><p class="muted">Belum ada tugas dibuat.</p><?php endif; ?></div>
<?php require 'includes/footer.php'; ?>